package offline;

/**
 * Minimal QUIC unsigned variable length integer helpers (RFC 9000 section 16).
 *
 * <p>Header and body integers may use any legal width (overlong encodings are accepted when
 * decoding); frame types however must use the shortest possible encoding.</p>
 */
public final class QuicVarint {

    /** Largest value representable by a QUIC varint (2^62-1). */
    public static final long MAX_VALUE = (1L << 62) - 1;

    private QuicVarint() {
    }

    /** Number of bytes the minimal encoding of {@code value} needs. */
    public static int size(long value) {
        if (value < 0 || value > MAX_VALUE) {
            throw new IllegalArgumentException("value not encodable: " + value);
        }
        if (value <= 63) {
            return 1;
        }
        if (value <= 16383) {
            return 2;
        }
        if (value <= 1073741823L) {
            return 4;
        }
        return 8;
    }

    /** Minimal encoding of {@code value}. */
    public static byte[] encode(long value) {
        int length = size(value);
        byte[] out = new byte[length];
        long rest = value;
        for (int i = length - 1; i >= 0; i--) {
            out[i] = (byte) (rest & 0xFF);
            rest >>>= 8;
        }
        if (length == 2) {
            out[0] |= (byte) 0x40;
        } else if (length == 4) {
            out[0] |= (byte) 0x80;
        } else if (length == 8) {
            out[0] |= (byte) 0xC0;
        }
        return out;
    }

    /**
     * Decodes the varint starting at {@code offset}.
     *
     * @return the number of consumed bytes or -1 when the encoding is truncated
     */
    public static int decode(byte[] data, int offset, int end, long[] out) {
        if (offset >= end) {
            return -1;
        }
        int first = data[offset] & 0xFF;
        int length = 1 << (first >>> 6);
        if (offset + length > end) {
            return -1;
        }
        long value = first & 0x3F;
        for (int i = 1; i < length; i++) {
            value = (value << 8) | (data[offset + i] & 0xFF);
        }
        out[0] = value;
        return length;
    }
}
