package offline;

import java.util.ArrayDeque;
import java.util.HashMap;
import java.util.Map;

/**
 * Undo log of a single packet transaction. Every mutation of the receive state registers its
 * inverse so that a failing packet can be rolled back completely.
 */
public final class Journal {

    public interface Undo {
        void run();
    }

    private final ArrayDeque<Undo> undos = new ArrayDeque<>();
    private final Map<ByteStore, Map<Long, ByteStore.Chunk>> chunkSnapshots = new HashMap<>();

    public void add(Undo undo) {
        undos.add(undo);
    }

    /** Stores the pre-modification content of a byte store chunk (once per transaction). */
    public void snapshotChunk(ByteStore store, long index, ByteStore.Chunk copy) {
        Map<Long, ByteStore.Chunk> perStore = chunkSnapshots.get(store);
        if (perStore == null) {
            perStore = new HashMap<>();
            chunkSnapshots.put(store, perStore);
        }
        if (perStore.containsKey(index)) {
            return;
        }
        perStore.put(index, copy);
        undos.add(() -> store.restoreChunk(index, copy));
    }

    public void rollback() {
        while (!undos.isEmpty()) {
            undos.pop().run();
        }
        chunkSnapshots.clear();
    }

    public void commit() {
        undos.clear();
        chunkSnapshots.clear();
    }
}
